function lemlistSecretMatches(supplied, expected) {
  if (
    typeof supplied !== "string" ||
    typeof expected !== "string" ||
    !/^[0-9a-f]{64}$/.test(supplied) ||
    !/^[0-9a-f]{64}$/.test(expected)
  )
    return false;
  let difference = 0;
  for (let i = 0; i < 64; i++) difference |= supplied.charCodeAt(i) ^ expected.charCodeAt(i);
  return difference === 0;
}

function normalizedLemlistReply(
  { body, authenticated, teamId, slackChannel },
  singleMailbox,
  plainMail,
) {
  if (!authenticated) return { httpStatus: 401, process: false, event: null };
  if (!/^tea_[A-Za-z0-9]{3,80}$/.test(teamId) || !/^[CG][A-Z0-9]{8,30}$/.test(slackChannel)) {
    return { httpStatus: 503, process: false, event: null };
  }
  if (!body || body.teamId !== teamId) return { httpStatus: 403, process: false, event: null };
  if (body.type !== "emailsReplied" || body.isThirdPartyReply === true)
    return { httpStatus: 202, process: false, event: null };
  const { _id, leadId, campaignId, contactId, leadEmail, sendUserEmail } = body;
  if (
    !/^act_[A-Za-z0-9]{3,80}$/.test(_id) ||
    !/^lea_[A-Za-z0-9]{3,80}$/.test(leadId) ||
    !/^cam_[A-Za-z0-9]{3,80}$/.test(campaignId) ||
    (contactId != null && !/^ctc_[A-Za-z0-9]{3,80}$/.test(contactId)) ||
    !singleMailbox(leadEmail) ||
    singleMailbox(leadEmail) !== leadEmail ||
    typeof body.text !== "string" ||
    body.text.length > 60000
  )
    return { httpStatus: 400, process: false, event: null };
  const withoutQuotes = body.text.replace(/<blockquote\b[^>]*>[\s\S]*?<\/blockquote\s*>/gi, "");
  const text = plainMail("", withoutQuotes)
    .split(/\n(?=On [^\n]{1,200} wrote:|>)/i, 1)[0]
    .trim();
  if (!text || text.length > 24000) return { httpStatus: 400, process: false, event: null };
  const cleanField = (value) =>
    typeof value === "string"
      ? value
          .replace(/[\x00-\x1f\x7f]/g, " ")
          .trim()
          .slice(0, 250)
      : "";
  const event = {
    id: _id,
    key: teamId + ":" + _id,
    teamId,
    leadId,
    campaignId,
    contactId: contactId ?? null,
    leadEmail,
    sender: singleMailbox(sendUserEmail),
    careerUrl: cleanField(body.linkedinUrl),
    campaignName: cleanField(body.campaignName ?? body.name),
    text,
    slackChannel,
  };
  return { httpStatus: 202, process: true, event };
}

function singleMailbox(value) {
  if (typeof value !== "string" || /[\r\n\x00]/.test(value)) return "";
  const text = value.trim();
  const named = text.match(/^(?:[^<>,;]+|"[^"\r\n]+")\s*<([^<>]+)>$/);
  const address = named ? named[1] : text;
  return /^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+$/.test(address) &&
    address.length <= 254
    ? address
    : "";
}

function plainMail(text, html) {
  const source =
    typeof text === "string" && text.trim()
      ? text
      : String(html ?? "")
          .replace(/<(script|style|head)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, "")
          .replace(/<br\s*\/?>|<\/(?:p|div|li|h[1-6]|tr)>/gi, "\n")
          .replace(/<[^>]*>/g, "")
          .replace(
            /&(?:amp|lt|gt|quot|apos|nbsp|#39);/gi,
            (value) =>
              ({ amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " ", "#39": "'" })[
                value.slice(1, -1).toLowerCase()
              ],
          );
  return source
    .replace(/\r\n?/g, "\n")
    .replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}
export default ({ body, expectedSecret, teamId, slackChannel }) => {
  return normalizedLemlistReply(
    {
      body,
      authenticated: lemlistSecretMatches(body?.secret, expectedSecret),
      teamId,
      slackChannel,
    },
    singleMailbox,
    plainMail,
  );
};

