function lemlistSlackAlert(event, category) {
  const field = (label, value) => ({
    type: "plain_text",
    text: label + "\n" + (value || "Unavailable"),
    emoji: false,
  });
  const escaped = (text) =>
    text
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll("|", " ");
  const campaignLink =
    "https://app.lemlist.com/teams/" + event.teamId + "/reports/campaigns/" + event.campaignId;
  return {
    channelId: event.slackChannel,
    text: "New lemlist reply: " + category,
    unfurlLinks: false,
    unfurlMedia: false,
    blocks: [
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text:
            "*New reply in lemlist*\nCampaign: <" +
            campaignLink +
            "|" +
            escaped(event.campaignName || event.campaignId) +
            ">",
        },
      },
      {
        type: "section",
        fields: [
          field("Category", category),
          field("Sender", event.sender),
          field("Lead", event.leadEmail),
          field("LinkedIn URL", event.careerUrl),
        ],
      },
      { type: "section", text: field("Reply preview", [...event.text].slice(0, 100).join("")) },
    ],
  };
}

function slackLemlistReceipt(reply, channel) {
  return reply?.channelId === channel && typeof reply.ts === "string" && /^\d+\.\d+$/.test(reply.ts)
    ? { state: "confirmed", ts: reply.ts }
    : { state: "unconfirmed" };
}
export default async ({ event, category }, context) => {
  try {
    const result = await context.actions.call(
      "slack.post_message",
      lemlistSlackAlert(event, category),
    );
    return { slack: slackLemlistReceipt(result, event.slackChannel) };
  } catch {
    return { slack: { state: "unconfirmed" } };
  }
};

